import hashlib
import os

def get_file_hash(file_path):
    sha256_hash = hashlib.sha256()
    try:
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()
    except Exception as e:
        return None

def find_duplicates(root_dir):
    hashes = {}

    for root, dirs, files in os.walk(root_dir):
        for filename in files:
            file_path = os.path.join(root, filename)
            file_hash = get_file_hash(file_path)

            if file_hash is not None:
                # Get relative path with forward slashes
                rel_path = os.path.relpath(file_path, root_dir).replace(os.sep, '/')
                if file_hash not in hashes:
                    hashes[file_hash] = []
                hashes[file_hash].append(rel_path)

    # Filter groups with at least 2 files
    duplicate_groups = [paths for paths in hashes.values() if len(paths) > 1]

    # Sort each group alphabetically
    for group in duplicate_groups:
        group.sort()

    # Sort the list of groups by the first element of each group
    duplicate_groups.sort(key=lambda x: x[0])

    return duplicate_groups

if __name__ == "__main__":
    root = "dosyalar"
    if os.path.exists(root):
        groups = find_duplicates(root)
        with open("kopyalar.txt", "w", encoding="utf-8") as f:
            for group in groups:
                f.write(" | ".join(group) + "\n")
        print(f"Found {len(groups)} groups.")
    else:
        print(f"Directory '{root}' not found.")

